410	typedef struct {
411	    const char *name;
412	    const char *key;
413	    void *value;
414	    int fail_at;           /* 0 = no injected malloc failure */
415	    int expect_ok;         /* expect rb_insert to return 0 */
416	    int expect_free_count; /* rb_free calls during the faulted insert; -1 = n/a */
417	} insert_case_t;
418	
419	/* Cases 1-3: baseline success, and injected failure on each of
420	 * rb_insert's internal allocations. Order-agnostic about which
421	 * allocation (node struct vs. key copy) fail_at hits -- the header's
422	 * -1 contract must hold identically either way.
423	 *
424	 * expect_free_count mirrors create_cases' reasoning: fail_at=1 fails on the
425	 * very first rb_malloc call (the node struct), before anything else is
426	 * allocated, so cleanup frees nothing (0); fail_at=2 fails on the second call
427	 * (the key copy) after the node struct already succeeded, so cleanup frees
428	 * exactly that one allocation (1). */
429	static const insert_case_t insert_cases[] = {
430	    { "insert_into_empty_success", "alpha", "alpha-value", 0, 1, -1 },
431	    { "insert_fails_first_alloc",  "beta",  "beta-value",  1, 0,  0 },
432	    { "insert_fails_second_alloc", "gamma", "gamma-value", 2, 0,  1 },
433	};
434	
435	static void test_rb_insert(void)
436	{
437	    size_t n = sizeof insert_cases / sizeof insert_cases[0];
438	    /* invariant: each iteration gets a fresh tree, so a case's outcome
439	     * never depends on a prior case's inserts. */
440	    for (size_t i = 0; i < n; i++) {
441	        const insert_case_t *c = &insert_cases[i];
442	        rbtree_t *t = rb_create(NULL);
443	        assert(t);
444	
445	        if (c->fail_at)
446	            fault_malloc_arm(c->fail_at);
447	        int rc = rb_insert(t, c->key, c->value);
448	        if (c->fail_at) {
449	            assert(fault_malloc_free_count() == c->expect_free_count);
450	            fault_malloc_disarm();
451	        }
452	
453	        assert((rc == 0) == c->expect_ok);
454	        assert(rb_size(t) == (size_t)(c->expect_ok ? 1 : 0));
455	        assert(rb_find(t, c->key) == (c->expect_ok ? c->value : NULL));
456	
457	        rb_destroy(t);
458	        printf("ok - %s\n", c->name);
459	    }
460	
461	    /* Case 4: on allocation failure the tree must not call value_free,
462	     * and the caller must retain sole ownership of value. */
463	    {
464	        rbtree_t *t = rb_create(track_free);
465	        assert(t);
466	        for (int fail_at = 1; fail_at <= 2; fail_at++) {
467	            reset_tracking();
468	            char *v = malloc(8);
469	            assert(v);
470	            strcpy(v, "owned");
471	
472	            fault_malloc_arm(fail_at);
473	            int rc = rb_insert(t, "delta", v);
474	            fault_malloc_disarm();
475	
476	            assert(rc == -1);
477	            assert(!was_freed(v));
478	            assert(rb_size(t) == 0);
479	            free(v);   /* caller still owns it; must not double-free */
480	        }
481	        rb_destroy(t);
482	        printf("ok - insert_failure_value_not_consumed\n");
483	    }
484	
485	    /* Case 5: overwriting an existing key frees the old value via
486	     * value_free, keeps size unchanged, and matches by key content (two
487	     * distinct buffers with identical content, not the same pointer). */
488	    {
489	        rbtree_t *t = rb_create(track_free);
490	        assert(t);
491	        reset_tracking();
492	
493	        char key_first[] = "dup";
494	        char key_second[] = "dup";
495	        char *old_value = malloc(8);
496	        char *new_value = malloc(8);
497	        assert(old_value && new_value);
498	        strcpy(old_value, "old");
499	        strcpy(new_value, "new");
500	
501	        assert(rb_insert(t, key_first, old_value) == 0);
502	        assert(rb_insert(t, key_second, new_value) == 0);
503	
504	        assert(rb_size(t) == 1);
505	        assert(was_freed(old_value));
506	        assert(free_occurrences(old_value) == 1); /* not freed twice */
507	        assert(!was_freed(new_value));
508	        assert(rb_find(t, "dup") == new_value);
509	
510	        /* A second overwrite of the same key, armed so the very first
511	         * rb_malloc call would fail: overwriting an existing key must not
512	         * allocate a new node or key copy (the key is already stored), so a
513	         * correct rb_insert makes zero rb_malloc/rb_free calls here and
514	         * still returns 0 despite the arming. An implementation that always
515	         * allocates a fresh node on every insert (even for a duplicate key)
516	         * would either fail here or leak the discarded new node/key. */
517	        int since = freed_count;   /* old_value's slot may get reused below */
518	        char *third_value = malloc(8);
519	        assert(third_value);
520	        strcpy(third_value, "third");
521	        fault_malloc_arm(1);
522	        int rc = rb_insert(t, "dup", third_value);
523	        assert(fault_malloc_free_count() == 0);
524	        fault_malloc_disarm();
525	        assert(rc == 0);
526	
527	        assert(rb_size(t) == 1);
528	        assert(free_occurrences_since(new_value, since) == 1); /* freed once, not twice */
529	        assert(!was_freed_since(third_value, since));
530	        assert(rb_find(t, "dup") == third_value);
531	
532	        /* A couple more surviving entries, so destroy has to walk multiple
533	         * nodes, not just the one left over from the overwrites. */
534	        char *extra1 = malloc(8);
535	        char *extra2 = malloc(8);
536	        assert(extra1 && extra2);
537	        strcpy(extra1, "extra1");
538	        strcpy(extra2, "extra2");
539	        assert(rb_insert(t, "extra-key-1", extra1) == 0);
540	        assert(rb_insert(t, "extra-key-2", extra2) == 0);
541	
542	        /* The repeated overwrite must have updated the existing node in
543	         * place, not left a stale second "dup" node behind: exactly 3
544	         * distinct keys should be visible to both validate and foreach. */
545	        assert(rb_validate(t) == 0);
546	        collect_ctx_t after_overwrite = {0};
547	        rb_foreach(t, collect_cb, &after_overwrite);
548	        assert(after_overwrite.n == 3);
549	
550	        rb_destroy(t);
551	        /* rb_destroy must run value_free on every value still owned by the
552	         * tree, not just the ones already freed by the earlier overwrites. */
553	        assert(was_freed(third_value));
554	        assert(was_freed(extra1));
555	        assert(was_freed(extra2));
556	        assert(freed_count == 5); /* old_value + new_value (overwrites) + 3 by destroy */
557	        printf("ok - insert_overwrite_frees_old_value\n");
558	    }
559	
560	    /* Case 6: distinct keys each get their own slot; size accumulates
561	     * and lookups don't cross-contaminate. Keys are inserted from mutable
562	     * buffers that get scribbled over right after each insert returns --
563	     * if rb_insert stored the caller's pointer instead of rb_malloc+memcpy
564	     * copying it, the lookups below would see the mutated content instead
565	     * of the original key. */
566	    {
567	        rbtree_t *t = rb_create(NULL);
568	        assert(t);
569	        char buf_a[] = "a-key", buf_m[] = "m-key", buf_z[] = "z-key";
570	        assert(rb_insert(t, buf_a, "a-value") == 0);
571	        assert(rb_insert(t, buf_m, "m-value") == 0);
572	        assert(rb_insert(t, buf_z, "z-value") == 0);
573	        memset(buf_a, 'X', strlen(buf_a));
574	        memset(buf_m, 'X', strlen(buf_m));
575	        memset(buf_z, 'X', strlen(buf_z));
576	
577	        assert(rb_size(t) == 3);
578	        assert(strcmp(rb_find(t, "a-key"), "a-value") == 0);
579	        assert(strcmp(rb_find(t, "m-key"), "m-value") == 0);
580	        assert(strcmp(rb_find(t, "z-key"), "z-value") == 0);
581	        assert(rb_find(t, "q-key") == NULL);
582	        assert(rb_find(t, "XXXXX") == NULL);
583	
584	        rb_destroy(t);
585	        printf("ok - insert_distinct_keys_prove_key_copy\n");
586	    }
