588	    /* Case 7: an ascending run of inserts forces left-rotations during
589	     * insert-fixup; rebalancing must preserve red-black invariants and
590	     * BST (sorted in-order) structure. */
591	    {
592	        static const char *keys[] = { "a", "b", "c", "d", "e", "f", "g" };
593	        size_t run_len = sizeof keys / sizeof keys[0];
594	        rbtree_t *t = rb_create(NULL);
