886	        assert(heap_key);
887	        strcpy(heap_key, "epsln");
888	        assert(rb_insert(t, heap_key, "epsilon-value") == 0);
889	        free(heap_key);
890	
891	        assert(rb_size(t) == 1);
892	        assert(strcmp(rb_find(t, "epsln"), "epsilon-value") == 0);
893	
894	        collect_ctx_t collected = {0};
895	        rb_foreach(t, collect_cb, &collected);
896	        assert(collected.n == 1);
897	        assert(strcmp(collected.keys[0], "epsln") == 0);
898	
899	        rb_destroy(t);
900	        printf("ok - insert_key_survives_caller_free\n");
901	    }
902	
903	    /* Case 16: a multi-level recolor. Inserting "m","f","t" leaves m black
904	     * (root-forced) with f and t red (no fixup loop runs, since m is
905	     * black). Inserting "d" as f's left child creates a red-red violation
906	     * (d red, parent f red) with a red uncle (t) -- Case 1 recolors f and t
907	     * black and m red, then the loop's next iteration sees m's parent is
908	     * nil (black) and stops, leaving m red until the trailing
909	     * `t->root->color = RB_BLACK` forces it back to black. Inserting "h" as
910	     * f's right child then hits no violation at all (f is black by then).
911	     * This pins down that the final forced-black-root line is load-bearing,
912	     * not a no-op -- deleting it would leave m red here, and rb_validate
913	     * would catch it, but this also checks the exact resulting shape/colors
914	     * a validate()-only check could miss if two bugs happened to cancel out. */
915	    {
916	        static const char *keys[] = { "m", "f", "t", "d", "h" };
917	        rbtree_t *t = rb_create(NULL);
918	        assert(t);
919	        for (size_t i = 0; i < sizeof keys / sizeof keys[0]; i++)
920	            assert(rb_insert(t, keys[i], (void *)keys[i]) == 0);
921	        assert(rb_size(t) == 5);
922	        assert(rb_validate(t) == 0);
923	
924	        rbnode_t *m = t->root;
925	        assert(strcmp(m->key, "m") == 0 && m->color == RB_BLACK);
926	        assert(m->parent == t->nil);
927	
928	        rbnode_t *f = m->left, *tt = m->right;
929	        assert(strcmp(f->key, "f") == 0 && f->color == RB_BLACK && f->parent == m);
930	        assert(strcmp(tt->key, "t") == 0 && tt->color == RB_BLACK && tt->parent == m);
931	        assert(tt->left == t->nil && tt->right == t->nil);
932	
933	        rbnode_t *d = f->left, *h = f->right;
934	        assert(strcmp(d->key, "d") == 0 && d->color == RB_RED && d->parent == f);
935	        assert(strcmp(h->key, "h") == 0 && h->color == RB_RED && h->parent == f);
936	        assert(d->left == t->nil && d->right == t->nil);
937	        assert(h->left == t->nil && h->right == t->nil);
938	
939	        collect_ctx_t collected = {0};
940	        rb_foreach(t, collect_cb, &collected);
941	        static const char *sorted[] = { "d", "f", "h", "m", "t" };
942	        assert(collected.n == 5);
943	        for (int i = 0; i < collected.n; i++)
944	            assert(strcmp(collected.keys[i], sorted[i]) == 0);
945	
946	        rb_destroy(t);
947	        printf("ok - insert_fixup_recolor_reaches_root\n");
948	    }
949	
950	    /* Case 17: rb_destroy must free every real rb_insert-built node (struct
951	     * + key copy) plus nil and the tree struct, and must run value_free on
952	     * every still-owned value, across a tree actually shaped by fixup
953	     * rotations -- not just the mk_node fixtures destroy_and_check_frees's
954	     * other callers use. */
955	    {
956	        rbtree_t *t = rb_create(track_free);
957	        assert(t);
958	        reset_tracking();
959	
960	        static const char *keys[] = { "delta", "alpha", "gamma", "beta" };
961	        size_t n = sizeof keys / sizeof keys[0];
962	        void *values[4];
963	        for (size_t i = 0; i < n; i++) {
964	            values[i] = malloc(8);
965	            assert(values[i]);
966	            strcpy(values[i], keys[i]);
967	            assert(rb_insert(t, keys[i], values[i]) == 0);
968	        }
969	        assert(rb_size(t) == n);
970	        assert(rb_validate(t) == 0);
971	
972	        fault_malloc_arm(0);          /* never fails; just resets the free counter */
973	        rb_destroy(t);
974	        assert(fault_malloc_free_count() == (int)n * 2 + 2);
975	        fault_malloc_disarm();
976	
977	        for (size_t i = 0; i < n; i++)
978	            assert(was_freed(values[i]));
979	        assert(freed_count == (int)n);
980	        printf("ok - insert_destroy_frees_real_nodes\n");
981	    }
982	}
983	
984	int main(void)
985	{
986	    test_rb_validate();
987	    test_rb_create();
988	    test_rb_insert();
989	    return 0;
990	}

